"""Inheritance flags for the objects the host hands to its helpers."""

import threading

from .errors import WSpawnError
from ._winapi import (
    HANDLE_FLAG_INHERIT,
    get_handle_information,
    set_handle_information,
)


# Internal registry of handles that have been marked inheritable through this
# module.  ``inheritable_handles()`` reports the subset that is still marked.
_tracked = set()
_lock = threading.Lock()


def _as_number(handle):
    try:
        return int(handle)
    except (TypeError, ValueError):
        raise WSpawnError(
            "handle must be an integer, got %r" % (handle,), kind="badarg"
        )


def set_inheritable(handle, enabled=True):
    """Mark ``handle`` as transferable to child processes, or stop it being so."""
    number = _as_number(handle)
    try:
        if enabled:
            set_handle_information(number, HANDLE_FLAG_INHERIT, HANDLE_FLAG_INHERIT)
        else:
            set_handle_information(number, HANDLE_FLAG_INHERIT, 0)
    except OSError as exc:
        # Map known Windows errors to the right WSpawnError kind.
        winerr = getattr(exc, "winerror", None)
        # ERROR_INVALID_HANDLE (6) / ERROR_FILE_NOT_FOUND (2) etc.
        if winerr in (6, 2, 87):
            raise WSpawnError(str(exc), kind="unsupported", handle=handle) from exc
        raise WSpawnError(str(exc), kind="os", handle=handle) from exc

    with _lock:
        if enabled:
            _tracked.add(number)
        else:
            _tracked.discard(number)


def is_inheritable(handle):
    """Return ``True`` when ``handle`` is currently transferable."""
    number = _as_number(handle)
    try:
        flags = get_handle_information(number)
    except OSError as exc:
        winerr = getattr(exc, "winerror", None)
        if winerr in (6, 2, 87):
            raise WSpawnError(str(exc), kind="unsupported", handle=handle) from exc
        raise WSpawnError(str(exc), kind="os", handle=handle) from exc
    return bool(flags & HANDLE_FLAG_INHERIT)


def inheritable_handles():
    """Return every object in this process that is currently transferable.

    Reports the handles that were marked inheritable through
    :func:`set_inheritable` and are still flagged as such.
    """
    with _lock:
        snapshot = list(_tracked)

    # Filter out handles that are no longer actually inheritable (the caller
    # may have changed the flag through another path).
    result = []
    for h in snapshot:
        try:
            flags = get_handle_information(h)
            if flags & HANDLE_FLAG_INHERIT:
                result.append(h)
            else:
                with _lock:
                    _tracked.discard(h)
        except OSError:
            with _lock:
                _tracked.discard(h)
    return tuple(result)

"""Classification of the objects the host may hand to its helpers."""

from .errors import WSpawnError
from ._winapi import (
    FILE_TYPE_DISK,
    FILE_TYPE_CHAR,
    FILE_TYPE_PIPE,
    FILE_TYPE_UNKNOWN,
    get_file_type,
)


def handle_kind(handle):
    """Return ``"file"``, ``"pipe"``, ``"console"`` or ``"unknown"``.

    Raises :class:`WSpawnError` with ``kind="badarg"`` for non-integer input,
    and ``kind="unsupported"`` for invalid or unrecognisable handles.
    """
    try:
        number = int(handle)
    except (TypeError, ValueError):
        raise WSpawnError(
            "handle must be an integer, got %r" % (handle,), kind="badarg"
        )

    if number < 0:
        raise WSpawnError(
            "not a usable object handle: %r" % (handle,),
            kind="badarg",
            handle=handle,
        )

    try:
        ft = get_file_type(number)
    except OSError as exc:
        winerr = getattr(exc, "winerror", None)
        # ERROR_INVALID_HANDLE (6), etc.
        if winerr in (6, 2, 87):
            raise WSpawnError(
                str(exc), kind="unsupported", handle=handle
            ) from exc
        raise WSpawnError(str(exc), kind="os", handle=handle) from exc

    if ft == FILE_TYPE_DISK:
        return "file"
    if ft == FILE_TYPE_PIPE:
        return "pipe"
    if ft == FILE_TYPE_CHAR:
        return "console"
    # FILE_TYPE_UNKNOWN or anything else
    return "unknown"

"""Starting helper processes with a handover of the caller's objects."""

import os
import sys
import msvcrt
import subprocess

from .errors import WSpawnError
from ._winapi import (
    create_process_with_handle_list,
    wait_for_single_object,
    get_exit_code_process,
    terminate_process,
    close_handle,
)


class SpawnedProcess(object):
    """A helper process started by :func:`spawn`."""

    def __init__(self, process_handle, thread_handle, pid, inherit):
        self._process_handle = process_handle
        self._thread_handle = thread_handle
        self.inherit = tuple(inherit)
        self.pid = pid
        self.returncode = None

    def wait(self, timeout=None):
        if self.returncode is not None:
            return self.returncode
        if timeout is None:
            timeout_ms = 0xFFFFFFFF
        else:
            timeout_ms = int(timeout * 1000)
        wait_for_single_object(self._process_handle, timeout_ms)
        try:
            self.returncode = get_exit_code_process(self._process_handle)
        except OSError:
            pass
        return self.returncode

    def poll(self):
        if self.returncode is not None:
            return self.returncode
        # WAIT_TIMEOUT = 0x102
        ret = wait_for_single_object(self._process_handle, 0)
        if ret == 0:
            # Signalled — process exited.
            try:
                self.returncode = get_exit_code_process(self._process_handle)
            except OSError:
                pass
        return self.returncode

    def terminate(self):
        try:
            terminate_process(self._process_handle, 1)
        except OSError:
            pass

    def _close(self):
        if self._process_handle is not None:
            try:
                close_handle(self._process_handle)
            except OSError:
                pass
            self._process_handle = None
        if self._thread_handle is not None:
            try:
                close_handle(self._thread_handle)
            except OSError:
                pass
            self._thread_handle = None

    def __del__(self):
        self._close()


def _normalise_argv(argv):
    if isinstance(argv, (str, bytes)):
        raise WSpawnError(
            "argv must be a sequence of arguments, not a single string",
            kind="badarg",
        )
    try:
        items = [os.fspath(item) for item in argv]
    except TypeError as exc:
        raise WSpawnError(
            "argv must be an iterable of paths: %s" % exc, kind="badarg"
        ) from exc
    if not items:
        raise WSpawnError("argv must not be empty", kind="badarg")
    return items


def _normalise_handles(inherit):
    if inherit is None:
        return ()
    if isinstance(inherit, int):
        raise WSpawnError(
            "inherit must be a sequence of handles, not a single handle",
            kind="badarg",
        )
    try:
        return tuple(int(item) for item in inherit)
    except (TypeError, ValueError) as exc:
        raise WSpawnError(
            "inherit must contain integer handles: %s" % exc, kind="badarg"
        ) from exc


def _resolve_std_handle(spec):
    """Turn a stdin/stdout/stderr spec into a Win32 HANDLE or None.

    Accepts:
    - ``None`` → use current process standard handle
    - ``subprocess.DEVNULL`` → NULL handle
    - An integer file descriptor → convert via msvcrt
    - A Python file object with a ``.fileno()`` method
    - An integer that is already a Win32 HANDLE (heuristic: too large for fd)
    """
    if spec is None:
        return None
    if spec is subprocess.DEVNULL:
        return None  # Will map to INVALID_HANDLE_VALUE in STARTUPINFO
    if hasattr(spec, "fileno"):
        fd = spec.fileno()
        try:
            return msvcrt.get_osfhandle(fd)
        except (OSError, ValueError):
            return fd
    if isinstance(spec, int):
        # Could be a raw HANDLE or an fd.  Try fd first.
        try:
            return msvcrt.get_osfhandle(spec)
        except (OSError, ValueError):
            return spec
    raise WSpawnError(
        "stdin/stdout/stderr must be None, DEVNULL, an fd, or a file object",
        kind="badarg",
    )


def _build_command_line(argv):
    """Build a Windows command line string from an argument list.

    Uses ``subprocess.list2cmdline`` which follows the MS C runtime quoting
    rules.
    """
    return subprocess.list2cmdline(argv)


def spawn(argv, inherit=(), stdin=None, stdout=None, stderr=None):
    """Start a helper process, handing it the objects named in ``inherit``.

    Returns a :class:`SpawnedProcess`.
    """
    command = _normalise_argv(argv)
    handles = _normalise_handles(inherit)

    cmd_line = _build_command_line(command)

    # Resolve standard streams to Win32 handles.
    stdin_h = _resolve_std_handle(stdin)
    stdout_h = _resolve_std_handle(stdout)
    stderr_h = _resolve_std_handle(stderr)

    try:
        proc_h, thread_h, pid, tid = create_process_with_handle_list(
            cmd_line,
            handle_list=list(handles),
            stdin_handle=stdin_h,
            stdout_handle=stdout_h,
            stderr_handle=stderr_h,
        )
    except OSError as exc:
        winerr = getattr(exc, "winerror", None)
        # ERROR_FILE_NOT_FOUND (2), ERROR_PATH_NOT_FOUND (3), etc.
        if winerr in (2, 3, 267):
            raise WSpawnError(str(exc), kind="os") from exc
        raise WSpawnError(str(exc), kind="os") from exc

    # Close the thread handle immediately; we don't need it.
    try:
        close_handle(thread_h)
        thread_h = None
    except OSError:
        pass

    return SpawnedProcess(proc_h, thread_h, pid, handles)

